examples:
//-- requests permission to change linkes, then breaks all links on touch.
default
{
state_entry
(){
llRequestPermissions
(
llGetOwner
(),
PERMISSION_CHANGE_LINKS
);
}
run_time_permissions
(
integer
vBitPermissions
){
if
(
PERMISSION_CHANGE_LINKS
&
vBitPermissions
){
state sMain
;
}
else
{
llResetScript
();
}
}
}
state sMain
{
touch_start
(
integer
vIntTouched
){
llBreakAllLinks
();
}
}
